 import AppDrawer from '@/components/AppDrawer';
 import { Dashboard } from '@/pages/Dashboard';
+import { NotFound } from '@/pages/NotFound'; // optional fallback

 function App() {
   return (
     <BrowserRouter>
       <AppDrawer /> {/* persists across pages */}
       <Routes>
-        {/* existing routes … */}
+        {/* Dashboard is the default route */}
+        <Route path="/" element={<Dashboard />} />
+        {/* keep your other routes below */}
+        <Route path="*" element={<NotFound />} />
       </Routes>
     </BrowserRouter>
   );
 }

 export default App;
```

> **Why:** Placing `<Dashboard />` at `/` makes it the landing page while preserving the drawer (which lives outside the route outlet).

---

### 2. Dashboard Page – `src/pages/Dashboard.tsx`

```tsx
import { Box, Container, Typography, Grid, CircularProgress } from '@mui/material';
import { useQuery } from '@tanstack/react-query';
import { apiClient } from '@/utils/apiClient';
import SummaryCard from '@/components/SummaryCard';
import RecentActivity from '@/components/RecentActivity';
import QuickActions from '@/components/QuickActions';
import { useTheme } from '@mui/material/styles';

export const Dashboard = () => {
  const theme = useTheme();

  // ---- Data fetching -------------------------------------------------
  const {
    data: summaryData,
    isLoading: isSummaryLoading,
    error: summaryError,
  } = useQuery(['dashboard-summary'], () =>
    apiClient.get('/dashboard/summary').then(res => res.data)
  );

  const {
    data: activityData,
    isLoading: isActivityLoading,
    error: activityError,
  } = useQuery(['dashboard-activity'], () =>
    apiClient.get('/dashboard/activity').then(res => res.data)
  );

  // ---- Render helpers ------------------------------------------------
  const renderError = (msg: string) => (
    <Typography color="error" sx={{ mb: 2 }}>
      {msg}
    </Typography>
  );

  return (
    <Box sx={{ pt: 3, pb: 4 }}>
      <Container maxWidth="lg">
        <Typography variant="h4" gutterBottom>
          Dashboard
        </Typography>

        {/* ---------- Summary Cards ---------- */}
        <Grid container spacing={3} sx={{ mb: 4 }}>
          {isSummaryLoading ? (
            <Grid item xs={12}>
              <CircularProgress size={48} />
            </Grid>
          ) : summaryError ? (
            <Grid item xs={12}>
              {renderError('Failed to load summary data')}
            </Grid>
          ) : (
            summaryData.map((card: SummaryCardProps) => (
              <Grid item xs={12} sm={6} md={4} key={card.id}>
                <SummaryCard {...card} />
              </Grid>
            ))
          )}
        </Grid>

        {/* ---------- Recent Activity & Quick Actions ---------- */}
        <Grid container spacing={3}>
          {/* Recent Activity – takes 7/12 on md+ */}
          <Grid item xs={12} md={8}>
            <Box sx={{ border: 1, borderColor: 'divider', borderRadius: 2, p: 2 }}>
              <Typography variant="h6" gutterBottom>
                Recent Activity
              </Typography>
              {isActivityLoading ? (
                <CircularProgress size={36} />
              ) : activityError ? (
                <renderError>Failed to load activity</renderError>
              ) : (
                <RecentActivity items={activityData} />
              )}
            </Box>
          </Grid>

          {/* Quick Actions – takes 5/12 on md+ */}
          <Grid item xs={12} md={4}>
            <Box sx={{ border: 1, borderColor: 'divider', borderRadius: 2, p: 2 }}>
              <Typography variant="h6" gutterBottom>
                Quick Actions
              </Typography>
              <QuickActions />
            </Box>
          </Grid>
        </Grid>
      </Container>
    </Box>
  );
};
```

**Explanation**

* Uses **React Query** to fetch summary & activity data in parallel.
* Shows a `CircularProgress` spinner while loading and an error message if the request fails.
* Layout:  
  * Summary cards – full‑width grid, responsive (`xs=12`, `sm=6`, `md=4`).  
  * Recent Activity (8/12 columns) + Quick Actions (4/12 columns) on `md+`; stacked on smaller screens.

