### 3. Summary Card Component – `src/components/SummaryCard.tsx`

```tsx
import { Card, CardContent, Typography, Stack } from '@mui/material';
import { useTheme } from '@mui/material/styles';

export interface SummaryCardProps {
  id: string | number;
  title: string;
  value: string | number;
  icon?: React.ReactNode; // optional MUI SvgIcon
  trend?: {
    direction: 'up' | 'down' | 'neutral';
    percent: number;
  };
  color?: 'primary' | 'secondary' | 'success' | 'error' | 'warning' | 'info';
}

const SummaryCard = ({
  title,
  value,
  icon,
  trend,
  color = 'primary',
}: SummaryCardProps) => {
  const theme = useTheme();
  const trendColor =
    trend?.direction === 'up'
      ? theme.palette.success.main
      : trend?.direction === 'down'
      ? theme.palette.error.main
      : theme.palette.text.secondary;

  return (
    <Card
      sx={{
        bgcolor: theme.palette.background.paper,
        boxShadow: 2,
        borderLeft: `4px solid ${theme.palette[color].main}`,
        minHeight: 140,
      }}
    >
      <CardContent sx={{ py: 2 }}>
        <Stack direction="row" alignItems="center" spacing={2}>
          {icon && <Box sx={{ fontSize: 28, color: theme.palette[color].main }}>{icon}</Box>}
          <Typography variant="h5" sx={{ flexGrow: 1 }}>
            {value}
          </Typography>
          {trend && (
            <Typography
              variant="body2"
              sx={{
                color: trendColor,
                display: 'flex',
                alignItems: 'center',
                gap: 0.5,
              }}
            >
              {trend.direction === 'up' && '▲'}
              {trend.direction === 'down' && '▼'}
              {trend.direction === 'neutral' && '◆'}
              {Math.abs(trend.percent)}%
            </Typography>
          )}
        </Stack>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
          {title}
        </Typography>
      </CardContent>
    </Card>
  );
};

export default SummaryCard;
```

*The card is deliberately simple – you can replace the icon with any MUI `SvgIcon` (e.g., `<PeopleIcon />`).*

