### 4. Recent Activity Component – `src/components/RecentActivity.tsx`

```tsx
import { List, ListItem, ListItemIcon, ListItemText, Avatar } from '@mui/material';
import { AccessTime, Person } from '@mui/icons-material';

export interface ActivityItem {
  id: string | number;
  timestamp: string; // ISO string – will be formatted
  user: { name: string; avatar?: string };
  action: string; // e.g., "Created project X"
  type: 'info' | 'success' | 'warning' | 'error';
}

const RecentActivity = ({ items }: { items: ActivityItem[] }) => {
  const formatTime = (iso: string) => {
    const d = new Date(iso);
    return d.toLocaleString(undefined, { hour: '2-digit', minute: '2-digit' });
  };

  const getIcon = (type: ActivityItem['type']) => {
    switch (type) {
      case 'success':
        return <Person color="success" />;
      case 'warning':
        return <AccessTime color="warning" />;
      case 'error':
        return <Person color="error" />;
      default:
        return <AccessTime color="info" />;
    }
  };

  return (
    <List sx={{ width: '100%' }}>
      {items.length === 0 ? (
        <ListItem>
          <ListItemText primary="No recent activity" />
        </ListItem>
      ) : (
        items.map((item) => (
          <ListItem key={item.id} sx={{ py: 1 }}>
            <ListItemIcon sx={{ minWidth: 36 }}>
              <Avatar sx={{ bgcolor: getIcon(item.type).props.color ?? 'grey' }}>
                {getIcon(item.type)}
              </Avatar>
            </ListItemIcon>
            <ListItemText
              primary={item.action}
              secondary={
                <>
                  <Typography variant="body2" color="text.secondary">
                    by {item.user.name}
                  </Typography>
                  <Typography variant="caption" color="text.secondary">
                    {formatTime(item.timestamp)}
                  </Typography>
                </>
              }
            />
          </ListItem>
        ))
      )}
    </List>
  );
};

export default RecentActivity;
