## 1. File‑by‑File Changes  

### 1.1 `src/pages/Dashboard.tsx`  

```tsx
// src/pages/Dashboard.tsx
import React, { useEffect, useState } from 'react';
import {
  Box,
  Grid,
  Typography,
  CircularProgress,
  Alert,
} from '@mui/material';
import { useParams, useNavigate } from 'react-router-dom';
import SummaryCard from '../components/SummaryCard';
import RecentActivity from '../components/RecentActivity';
import QuickActions from '../components/QuickActions';
import { apiClient } from '../utils/apiClient';
import { useAppDispatch } from '../store/hooks';
import { setUser } from '../store/userSlice';

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();

  // ----- State -----
  const [summary, setSummary] = useState<any>(null);
  const [activity, setActivity] = useState<any[]>([]);
  const [quickActions, setQuickActions] = useState<any[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // ----- Effects -----
  useEffect(() => {
    const fetchData = async () => {
      try {
        // Parallel requests – if any fails we go to catch
        const [
          summaryRes,
          activityRes,
          actionsRes,
        ] = await Promise.all([
          apiClient.get('/dashboard/summary'),
          apiClient.get('/dashboard/recent-activity'),
          apiClient.get('/dashboard/quick-actions'),
        ]);

        setSummary(summaryRes.data);
        setActivity(activityRes.data);
        setQuickActions(actionsRes.data);
      } catch (err: any) {
        // Normalise error message
        setError(
          err.response?.data?.message ||
          err.message ||
          'Failed to load dashboard data'
        );
      } finally {
        setLoading(false);
      }
    };

    // Optional: fetch user profile once and store in Redux (example)
    (async () => {
      try {
        const userRes = await apiClient.get('/me');
        dispatch(setUser(userRes.data));
      } catch (e) {
        // Non‑fatal – we still want the dashboard to show
        console.warn('Could not fetch user profile', e);
      }
    })();

    fetchData();
  }, [dispatch, navigate]);

  // ----- Render -----
  if (loading) {
    return (
      <Box sx={{ p: 3, minHeight: '100vh' }}>
        <Grid container justifyContent="center" alignItems="center" height="100%">
          <Grid item>
            <CircularProgress size={48} />
          </Grid>
        </Grid>
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ p: 3, minHeight: '100vh' }}>
        <Alert severity="error" sx={{ width: '100%', maxWidth: 480, mx: 'auto' }}>
          {error}
        </Alert>
      </Box>
    );
  }

  // Defensive: if data is still null (should not happen after loading=false)
  if (!summary) {
    return (
      <Box sx={{ p: 3, minHeight: '100vh' }}>
        <Alert severity="warning">
          Dashboard data is unavailable.
        </Alert>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3, minHeight: '100vh', bgcolor: 'background.default' }}>
      <Typography variant="h4" gutterBottom>
        Dashboard
      </Typography>

      {/* Summary Cards – responsive grid */}
      <Grid container spacing={2} mb={3}>
        {Object.entries(summary).map(([key, value]) => (
          <Grid
            item
            xs={12}          // mobile: full width
            sm={6}           // tablet: 2‑column
            md={4}           // desktop: 3‑column
            key={key}
          >
            <SummaryCard title={key} value={value} />
          </Grid>
        ))}
      </Grid>

      {/* Recent Activity */}
      <Box mb={3}>
        <Typography variant="h5" gutterBottom>
          Recent Activity
        </Typography>
        <RecentActivity items={activity} />
      </Box>

      {/* Quick Actions */}
      <Box>
        <Typography variant="h5" gutterBottom>
          Quick Actions
        </Typography>
        <QuickActions actions={quickActions} />
      </Box>
    </Box>
  );
};

export default Dashboard;
```

**What changed?**  

| Issue | Fix |
|-------|-----|
| Invalid JSX `{renderError>Failed to load activity</renderError>}` | Replaced with proper error handling via state (`error`) and `<Alert>` component. |
| Missing `Box` import in `SummaryCard.tsx` | Added `Box` to the import list in that file (see below). |
| Potential race condition / missing loading state | Introduced explicit `loading` boolean; shows `<CircularProgress>` while requests are in flight. |
| No error UI | Added `<Alert severity="error">` that renders when `error` is truthy. |
| No Redux user fetch (optional but useful) | Demonstrated how to dispatch a user profile fetch without blocking UI. |

