### 1. `src/pages/Dashboard.tsx`

```tsx
// src/pages/Dashboard.tsx
import React, { useEffect, useState } from 'react';
import { Box, CircularProgress, Typography, Grid, Card, CardContent } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import SummaryCard from '../components/SummaryCard';
import RecentActivity from '../components/RecentActivity';
import QuickActions from '../components/QuickActions';
import apiClient from '../api/apiClient';
import { useDispatch, useSelector } from 'react-redux';
import { setUser } from '../store/userSlice'; // example – adjust to your store

// Types (adjust if you already have them elsewhere)
interface SummaryData {
  [key: string]: number | string;
}
interface ActivityItem {
  id: string;
  description: string;
  timestamp: string;
}
interface QuickAction {
  id: string;
  label: string;
  icon: React.ComponentType<{ sx?: object }>;
  onClick: () => void;
}

const Dashboard: React.FC = () => {
  const theme = useTheme();
  const dispatch = useDispatch();
  const user = useSelector((state: any) => state.user); // adjust selector

  const [summary, setSummary] = useState<SummaryData | null>(null);
  const [activity, setActivity] = useState<ActivityItem[] | null>(null);
  const [quickActions, setQuickActions] = useState<QuickAction[] | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Fetch all three resources in parallel
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      setError(null);
      try {
        // NOTE: Adjust endpoints to match your backend
        const [summaryRes, activityRes, quickRes] = await Promise.all([
          apiClient.get<SummaryData>('/dashboard/summary'),
          apiClient.get<ActivityItem[]>('/dashboard/recent-activity'),
          apiClient.get<QuickAction[]>('/dashboard/quick-actions'),
        ]);

        setSummary(summaryRes.data);
        setActivity(activityRes.data);
        setQuickActions(quickRes.data);
      } catch (err: any) {
        console.error('Dashboard fetch error:', err);
        setError(err?.response?.data?.message ?? 'Failed to load dashboard');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [dispatch]); // re‑fetch if user/logout changes (optional)

  // Render loading spinner
  if (loading) {
    return (
      <Box sx={{ height: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
        <CircularProgress />
      </Box>
    );
  }

  // Render error message
  if (error) {
    return (
      <Box sx={{ p: 3, color: 'error.main' }}>
        <Typography variant="body1">{error}</Typography>
      </Box>
    );
  }

  // Guard – if data is still null (should not happen after loading false)
  if (!summary || !activity || !quickActions) {
    return <Box sx={{ p: 3 }}>Unexpected state – no data</Box>;
  }

  return (
    <Box sx={{ p: 3, minHeight: '100vh' }}>
      <Typography variant="h4" gutterBottom>
        Dashboard
      </Typography>

      {/* Summary Cards */}
      <Grid container spacing={3}>
        {Object.entries(summary).map(([key, value]) => (
          <Grid item xs={12} sm={6} md={4} key={key}>
            <SummaryCard title={key} value={value} />
          </Grid>
        ))}
      </Grid>

      {/* Recent Activity */}
      <Box sx={{ mt: 4 }}>
        <Typography variant="h6" gutterBottom>
          Recent Activity
        </Typography>
        <RecentActivity items={activity} />
      </Box>

      {/* Quick Actions */}
      <Box sx={{ mt: 4 }}>
        <Typography variant="h6" gutterBottom>
          Quick Actions
        </Typography>
        <QuickActions actions={quickActions} />
      </Box>
    </Box>
  );
};

export default Dashboard;
```

**Key fixes**

* **JSX error** – replaced `{renderError>Failed to load activity</renderError>}` with `{renderError('Failed to load activity')}` (the original snippet was removed entirely; we now use a dedicated error UI).  
* **Unused hooks** – removed `useParams` and `useNavigate` (they were not needed).  
* **Loading / error handling** – explicit states prevent rendering `undefined` data.  
* **Type safety** – added lightweight interfaces; adjust to match your actual API shape.  

