    // Grab the Grid container that holds the summary cards
    const summaryGrid = screen.getByRole('grid'); // MUI Grid renders role="grid"
    // The Grid items inside should have responsive classes applied via MUI's sx prop.
    // We can inspect the computed style for width at different viewport sizes.
    const checkColumnCount = (width: number, expected: number) => {
      // Resize window
      window.innerWidth = width;
      window.dispatchEvent(new Event('resize'));
      // Give React a moment to recalc
      return act(async () => {
        await waitFor(() => true);
        const items = summaryGrid.querySelectorAll('[role="gridcell"]'); // each Grid item
        return items.length; // number of rendered items (should match columns * rows)
      });
    };

    // Mobile (<600px) – expect 1 column → 3 items total (since we have 3 cards)
