### 4. Dashboard.tsx
*Main dashboard page with data fetching and error handling*

```typescript
import { useEffect, useState } from 'react';
import {
  Box,
  Typography,
  CircularProgress,
  Alert,
  Grid,
  Container
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import apiClient from '../api/apiClient';
import SummaryCard from './SummaryCard';
import RecentActivity from './RecentActivity';
import QuickActions from './QuickActions';

interface SummaryData {
  [key: string]: string | number;
}

interface DashboardProps {}

const Dashboard: React.FC<DashboardProps> = () => {
  const navigate = useNavigate();
  const [summaryData, setSummaryData] = useState<SummaryData | null>(null);
  const [summaryError, setSummaryError] = useState<string | null>(null);
  const [summaryLoading, setSummaryLoading] = useState<boolean>(true);

  const [recentActivityData, setRecentActivityData] = useState<any[] | null>(null);
  const [recentActivityError, setRecentActivityError] = useState<string | null>(null);
  const [recentActivityLoading, setRecentActivityLoading] = useState<boolean>(true);

  const [quickActionsData, setQuickActionsData] = useState<any[] | null>(null);
  const [quickActionsError, setQuickActionsError] = useState<string | null>(null);
  const [quickActionsLoading, setQuickActionsLoading] = useState<boolean>(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Fetch all data in parallel
        const [summaryRes, activityRes, actionsRes] = await Promise.all([
          apiClient.get('/api/summary'),
          apiClient.get('/api/recent-activity'),
          apiClient.get('/api/quick-actions')
        ]);

        setSummaryData(summaryRes.data);
        setRecentActivityData(activityRes.data);
        setQuickActionsData(actionsRes.data);
      } catch (err: any) {
        // Handle errors per endpoint
        if (err.response?.status === 404) {
          setSummaryError('Summary data not found');
          setRecentActivityError('Activity data not found');
          setQuickActionsError('Actions data not found');
        } else {
          setSummaryError('Failed to load summary');
          setRecentActivityError('Failed to load activity');
          setQuickActionsError('Failed to load actions');
        }
      } finally {
        setSummaryLoading(false);
        setRecentActivityLoading(false);
        setQuickActionsLoading(false);
      }
    };

    fetchData();
  }, []);

  // Handle navigation to detailed views
  const handleSummaryClick = (key: string) => {
    navigate(`/summary/${key}`);
  };

  return (
    <Container maxWidth="lx" sx={{ pt: 4 }}>
      <Typography variant="h4" gutterBottom align="center">
        Dashboard Overview
      </Typography>

      {/* Summary Cards Section */}
      <Box mb={4}>
        <Typography variant="h6" gutterBottom>
          Key Metrics
        </Typography>
        {summaryLoading ? (
          <CircularProgress />
        ) : summaryError ? (
          <Alert severity="error">{summaryError}</Alert>
        ) : (
          <Grid container spacing={3}>
            {Object.entries(summaryData!).map(([key, value]) => (
              <Grid item xs={12} sm={6} md={4} key={key}>
                <SummaryCard
                  title={key}
                  value={value}
                  dataTestId={`summary-card-${key}`}
                  onClick={() => handleSummaryClick(key)}
                  sx={{ cursor: 'pointer' }}
                >
                  <Typography variant="caption" color="text.secondary">
                    Click for details
                  </Typography>
                </SummaryCard>
              </Grid>
            ))}
          </Grid>
        )}
      </Box>

      {/* Recent Activity Section */}
      <Box mb={4}>
        {recentActivityLoading ? (
          <CircularProgress />
        ) : recentActivityError ? (
          <Alert severity="error">{recentActivityError}</Alert>
        ) : (
          <RecentActivity data={recentActivityData!} />
        )}
      </Box>

      {/* Quick Actions Section */}
      <Box>
        {quickActionsLoading ? (
          <CircularProgress />
        ) : quickActionsError ? (
          <Alert severity="error">{quickActionsError}</Alert>
        ) : (
          <QuickActions data={quickActionsData!} />
        )}
      </Box>
    </Container>
  );
};

export default Dashboard;
```

