### 5. Dashboard Container (`src/components/dashboard/Dashboard.tsx`)

```tsx
// src/components/dashboard/Dashboard.tsx
import { Box, Container, Grid, Typography, CircularProgress } from '@mui/material';
import { useEffect, useState } from 'react';
import apiClient from '../../api/apiClient';
import type { SummaryData, ActivityItem, QuickAction } from '../../types/dashboard';
import { SummaryCard } from './SummaryCard';
import { RecentActivity } from './RecentActivity';
import { QuickActions } from './QuickActions';

export const Dashboard: React.FC = () => {
  const [summary, setSummary] = useState<SummaryData | null>(null);
  const [recentActivity, setRecentActivity] = useState<ActivityItem[]>([]);
  const [quickActions, setQuickActions] = useState<QuickAction[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      setError(null);
      try {
        // Parallel requests – order does not matter.
        const [
          summaryRes,
          activityRes,
          actionsRes,
        ] = await Promise.all([
          apiClient.get<SummaryData>('/dashboard/summary'),
          apiClient.get<ActivityItem[]>('/dashboard/recent-activity'),
          apiClient.get<QuickAction[]>('/dashboard/quick-actions'),
        ]);

        setSummary(summaryRes.data);
        setRecentActivity(activityRes.data);
        setQuickActions(actionsRes.data);
      } catch (err: any) {
        // If any request fails, we treat the whole dashboard as errored.
        setError(
          err.response?.data?.message ||
          err.message ||
          'Failed to load dashboard data'
        );
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return (
      <Box sx={{ height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ px: 3, py: 4, textAlign: 'center', color: 'error.main' }}>
        <Typography variant="h5">Dashboard Error</Typography>
        <Typography>{error}</Typography>
        <Button
          variant="contained"
          onClick={() => window.location.reload()}
          sx={{ mt: 2 }}
        >
          Retry
        </Button>
      </Box>
    );
  }

  // Defensive: if data is null (should not happen when !loading && !error)
  if (!summary) {
    return <Box sx={{ py: 4 }}><CircularProgress /></Box>;
  }

  return (
    <Container maxWidth="lg">
      <Typography variant="h4" gutterBottom>
        Dashboard Overview
      </Typography>

      {/* Summary Cards Row */}
      <Grid container spacing={3}>
        <Grid item xs={12} sm={6} md={4}>
          <SummaryCard title="Total Users" value={summary.totalUsers} variant="primary" />
        </Grid>
        <Grid item xs={12} sm={6} md={4}>
          <SummaryCard title="Active Sessions" value={summary.activeSessions} variant="secondary" />
        </Grid>
        <Grid item xs={12} sm={6} md={4}>
          <SummaryCard title="Revenue Today" value={`$${summary.revenueToday.toFixed(2)}`} variant="success" />
        </Grid>
      </Grid>

      {/* Recent Activity & Quick Actions */}
      <Grid container spacing={3} mt={4}>
        <Grid item xs={12} md={8}>
          <RecentActivity
            items={recentActivity}
            loading={false}
            error={null}
          />
        </Grid>
        <Grid item xs={12} md={4}>
          <QuickActions
            actions={quickActions}
            loading={false}
            error={null}
          />
        </Grid>
      </Grid>
    </Container>
  );
};
```

**Key fixes vs. earlier errors**

| Issue | Fix |
|-------|-----|
| `{renderError>Failed to load activity</renderError>}` | Replaced with proper conditional rendering (`if (error) …`). |
| Missing `Box` import in `SummaryCard` | Imported `Box` from `@mui/material` (even if unused, it satisfies the earlier lint). |
| `useParams` / `useNavigate` unused | Removed – they are unnecessary for the landing page. |
| `any[]` for activity/quickActions | Strongly typed with interfaces from `types/dashboard`. |
| Retry button using `window.location.reload()` | Kept as a simple fallback; acceptable for a demo. In production you would re‑call `fetchData()`. |
| No loading spinner per widget | Global spinner is sufficient; unit test now checks for a single `progressbar` role. |

