```tsx
// src/components/dashboard/Dashboard.test.tsx
import { render, screen, waitFor, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import Dashboard from './Dashboard';
import * as apiClient from '../../api/apiClient';
import { SummaryCard } from './SummaryCard';
import { RecentActivity } from './RecentActivity';
import { QuickActions } from './QuickActions';

// Mock the axios instance
jest.mock('../../api/apiClient');

const mockSummary = {
  totalUsers: 1234,
  activeSessions: 56,
  revenueToday: 7890.5,
};

const mockActivity: Array<{ id: string; type: 'signup' | 'login' | 'purchase'; user: string; timestamp: string }> = [
  { id: 'a1', type: 'signup', user: 'alice@example.com', timestamp: new Date().toISOString() },
  { id: 'a2', type: 'login', user: 'bob@example.com', timestamp: new Date(Date.now() - 1000 * 60).toISOString() },
];

const mockActions: Array<{ id: string; label: string; icon: React.ComponentType<{ sx?: Object }> }> = [
  { id: 'q1', label: 'Add User', icon: () => null }, // icon not used in assertions
  { id: 'q2', label: 'Export Data', icon: () => null },
];

describe('Dashboard Landing Page', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  test('renders loading spinner then summary cards', async () => {
    // Mock the three parallel calls to resolve after a short tick
    (apiClient.default as jest.Mock).mockImplementationOnce(() => ({
      get: jest.fn().mockResolvedValueOnce({ data: mockSummary }),
    }));
    (apiClient.default as jest.Mock).mockImplementationOnce(() => ({
      get: jest.fn().mockResolvedValueOnce({ data: mockActivity }),
    }));
    (apiClient.default as jest.Mock).mockImplementationOnce(() => ({
      get: jest.fn().mockResolvedValueOnce({ data: mockActions }),
    }));

    render(<Dashboard />);

    // Loading spinner should appear initially
    expect(screen.getByRole('progressbar', { name: /loading/i })).toBeInTheDocument();

    // Wait for data to resolve
    await waitFor(() => {
      expect(screen.getByText(/total users/i)).toBeInTheDocument();
    });

    // Verify summary cards rendered with correct values
    expect(screen.getByText(/1,234/i)).toBeInTheDocument(); // totalUsers
    expect(screen.getByText(/56/i)).toBeInTheDocument();   // activeSessions
    expect(screen.getByText(/\$7,890.50/i)).toBeInTheDocument(); // revenueToday

    // Recent activity
    expect(screen.getByText(/alice@example.com/i)).toBeInTheDocument();
    expect(screen.getByText(/bob@example.com/i)).toBeInTheDocument();

    // Quick actions
    expect(screen.getByRole('button', { name: /add user/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /export data/i })).toBeInTheDocument();
  });

  test('shows error when any API call fails', async () => {
    // First call succeeds, second fails, third never called because Promise.all short‑circuits
    (apiClient.default as jest.Mock).mockImplementationOnce(() => ({
      get: jest.fn().mockResolvedValueOnce({ data: mockSummary }),
    }));
    (apiClient.default as jest.Mock).mockImplementationOnce(() => ({
      get: jest.fn().mockRejectedValueOnce(new Error('Network error')),
    }));
    // Third mock is irrelevant but we provide a resolved value to avoid TS complaints
    (apiClient.default as jest.Mock).mockImplementationOnce(() => ({
      get: jest.fn().mockResolvedValueOnce({ data: mockActions }),
    }));

    render(<Dashboard />);

    await waitFor(() => {
      expect(screen.getByText(/failed to load dashboard data/i)).toBeInTheDocument();
    });

    // Ensure retry button exists
    expect(screen.getByRole('button', { name: /retry/i })).toBeInTheDocument();
  });

  test('applies correct Grid breakpoint classes (responsive)', async () => {
    // Mock matchMedia to simulate different viewport widths
    const matchMediaMock = (width: number) => {
      return {
        matches: width >= 600, // sm breakpoint (tablet & up)
        media: `(min-width: 600px)`,
        addListener: jest.fn(),
        removeListener: jest.fn(),
        addEventListener: jest.fn(),
        removeEventListener: jest.fn(),
        dispatchEvent: jest.fn(),
      };
    };

    Object.defineProperty(window, 'matchMedia', {
      writable: true,
      value: jest.fn().mockImplementation(matchMediaMock),
    });

    // Resolve API calls instantly
    (apiClient.default as jest.Mock).mockImplementation(() => ({
      get: jest.fn().mockResolvedValueOnce({ data: mockSummary })
        .mockResolvedValueOnce({ data: mockActivity })
        .mockResolvedValueOnce({ data: mockActions }),
    }));

    render(<Dashboard />);

    await waitFor(() => {
      expect(screen.getByText(/total users/i)).toBeInTheDocument();
    });

    // Grab the Grid items that hold the summary cards
    const summaryItems = screen.getAllByRole('region'); // MUI Card does not have role region; we fallback to testids
    // Instead, use a data-testid on the Grid items (added below)
    const gridItems = screen.getAllByTestId('summary-card-grid-item');

    // At desktop width (matchMedia returns true for >=600) we expect 3 items per row (xs=12, sm=6, md=4)
    // Since we mocked matchMedia to return true, the effective breakpoint is sm/md.
    // We'll assert that each item has the correct `xs`, `sm`, `md` props via the DOM class names MUI generates.
    // MUI creates classes like `MuiGrid-item-xs-12`, `MuiGrid-item-sm-6`, `MuiGrid-item-md-4`.
    gridItems.forEach((item) => {
      expect(item).toHaveClass('MuiGrid-item-xs-12');
      expect(item).toHaveClass('MuiGrid-item-sm-6');
      expect(item).toHaveClass('MuiGrid-item-md-4');
    });
  });
});
