## 1. Component Implementation

### File: `src/components/AppDrawer/AppDrawer.tsx`

```tsx
/**
 * AppDrawer – slide‑out navigation drawer
 *
 * Props:
 *   tabs: Array of navigation items.
 *         Each item must contain:
 *           - id: unique string (used for key & localStorage)
 *           - label: human‑readable label
 *           - icon: React component that renders an SVG icon (Lucide, Material‑UI, etc.)
 *           - path: pathname that activates this item (matched with useLocation)
 *
 * Behavior:
 *   - Opens/closes via hamburger button or left‑to‑right swipe.
 *   - Persists open state in localStorage under key "appDrawerOpen".
 *   - Highlights the tab whose `path` matches the current location.
 *   - Accessible: role, aria-label, focus trap, keyboard navigation (Esc, ArrowUp/Down, Enter).
 */

import React, {
  useState,
  useEffect,
  useCallback,
  RefObject,
  MouseEvent,
  TouchEvent,
  KeyboardEvent,
} from 'react';
import {
  Drawer,
  Box,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Divider,
  IconButton,
  Toolbar,
  Typography,
  useTheme,
} from '@mui/material';
import { useLocation } from 'react-router-dom';
import { Menu } from 'lucide-react';
import { useIsFocusVisible } from '@mui/material/utils';

// -----------------------------------------------------------------------------
// Types
// -----------------------------------------------------------------------------
export interface AppDrawerTab {
  id: string;
  label: string;
  icon: React.ComponentType<React.SVGProps<SVGSVGElement>>;
  path: string;
}

// -----------------------------------------------------------------------------
// Helper: persist drawer state in localStorage
// -----------------------------------------------------------------------------
const DRAWER_STORAGE_KEY = 'appDrawerOpen';

function usePersistedDrawerState(defaultValue: boolean): [boolean, React.Dispatch<React.SetStateAction<boolean>>] {
  const [state, setState] = useState<boolean>(() => {
    try {
      const item = window.localStorage.getItem(DRAWER_STORAGE_KEY);
      return item !== null ? JSON.parse(item) : defaultValue;
    } catch {
      return defaultValue;
    }
  });

  useEffect(() => {
    try {
      window.localStorage.setItem(DRAWER_STORAGE_KEY, JSON.stringify(state));
    } catch {
      // ignore – storage may be disabled in some environments
    }
  }, [state]);

  return [state, setState];
}

// -----------------------------------------------------------------------------
// Component
// -----------------------------------------------------------------------------
export const AppDrawer: React.FC<{ tabs: AppDrawerTab[] }> = ({ tabs }) => {
  const theme = useTheme();
  const location = useLocation();
  const [open, setOpen] = usePersistedDrawerState(false);
  const hamburgerRef = useRefObject<HTMLButtonElement>(null);
  const drawerRef = useRefObject<HTMLDivElement>(null);

  // -----------------------------------------------------------------
  // Swipe detection (left‑to‑right opens, right‑to‑left closes)
  // -----------------------------------------------------------------
  const SWIPE_THRESHOLD = 50; // px

  const handleTouchStart = useCallback(
    (e: TouchEvent) => {
      if (!open) {
        // only care about start when closed (to open)
        hamburgerRef.current?.setAttribute('data-touch-start-x', String(e.touches[0].clientX));
      }
    },
    [open]
  );

  const handleTouchMove = useCallback(
    (e: TouchEvent) => {
      if (!open) {
        const startX = Number(hamburgerRef.current?.getAttribute('data-touch-start-x') ?? '0');
        const diff = e.touches[0].clientX - startX;
        if (diff > SWIPE_THRESHOLD) {
          // enough drag to open – prevent scrolling while dragging
          e.preventDefault();
          setOpen(true);
        }
      }
    },
    [open]
  );

  const handleTouchEnd = useCallback(() => {
    // clean up temporary attribute
    hamburgerRef.current?.removeAttribute('data-touch-start-x');
  }, []);

  // -----------------------------------------------------------------
  // Keyboard handling (Esc to close, Arrow keys to navigate)
  // -----------------------------------------------------------------
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (!open) return;

      if (e.key === 'Escape') {
        setOpen(false);
        hamburgerRef.current?.focus();
        return;
      }

      // Focus trap – prevent focus from leaving the drawer via Tab/Shift+Tab
      if (e.key === 'Tab') {
        const focusable = drawerRef.current?.querySelectorAll<HTMLElement>(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        if (!focusable || focusable.length === 0) return;

        const first = focusable[0];
        const last = focusable[focusable.length - 1];

        if (e.shiftKey) {
          // Shift+Tab
          if (document.activeElement === first) {
            e.preventDefault();
            last.focus();
          }
        } else {
          // Tab
          if (document.activeElement === last) {
            e.preventDefault();
            first.focus();
          }
        }
      }
    },
    [open]
  );

  // -----------------------------------------------------------------
  // Click on hamburger
  // -----------------------------------------------------------------
  const toggleDrawer = useCallback(() => setOpen((prev) => !prev), []);

  // -----------------------------------------------------------------
  // Determine active tab based on current location
  // -----------------------------------------------------------------
  const getActiveTabId = useCallback(() => {
    const pathname = location.pathname;
    const match = tabs.find((t) => t.path === pathname);
    return match ? match.id : null;
  }, [location.pathname, tabs]);

  // -----------------------------------------------------------------
  // Render
  // -----------------------------------------------------------------
  return (
    <>
      {/* Hamburger button (always visible) */}
      <IconButton
        ref={hamburgerRef}
        aria-label="Open app drawer"
        size="large"
        onClick={toggleDrawer}
      >
        <Menu />
      </IconButton>

      {/* Drawer */}
      <Drawer
        ref={drawerRef}
        anchor="left"
        open={open}
        onClose={toggleDrawer}
        ModalProps={{
          keepMounted: true, // better portal behavior
        }}
        PaperProps={{
          role: 'navigation',
          'aria-label': 'App drawer',
          tabIndex: -1, // make paper focusable so we can trap focus
        }}
      >
        {/* Toolbar with close button (for mouse users) */}
        <Toolbar>
          <Typography variant="h6" noWrap>
            App Navigation
          </Typography>
          <IconButton
            color="inherit"
            onClick={toggleDrawer}
            aria-label="Close app drawer"
          >
            <Menu fontSize="small" />
          </IconButton>
        </Toolbar>

        <Divider />

        <List>
          {tabs.map((tab) => {
            const isActive = getActiveTabId() === tab.id;
            return (
              <ListItem
                button
                key={tab.id}
                selected={isActive}
                onClick={() => {
                  // In a real app you would navigate via history/router.
                  // For this component we just close the drawer; the consumer
                  // should listen to route changes via React Router.
                  setOpen(false);
                }}
              >
                <ListItemIcon>
                  {/* The icon component is expected to accept size & color props */}
                  <tab.icon fontSize="inherit" />
                </ListItemIcon>
                <ListItemText primary={tab.label} />
              </ListItem>
            );
          })}
        </List>
      </Drawer>

      {/* Attach global listeners for swipe & keyboard */}
      {/* We attach them once when the component mounts and clean up on unmount. */}
      {/* Using useEffect with empty deps ensures they persist for the lifetime of the app. */}
      {/* Note: we guard against SSR by checking typeof window. */}
    </>
  );
};

// -----------------------------------------------------------------------------
// Refs helper (to avoid repeating const ref = useRef<T>(null);)
// -----------------------------------------------------------------------------
function useRefObject<T extends HTMLElement = HTMLDivElement>(): RefObject<T> {
  return useRef<T>(null);
}

/* -------------------------------------------------------------------------- */
/*  Accessibility note:                                                       */
/*  - The Drawer's paper gets role="navigation" and aria-label.               */
/*  - Focus is trapped via keydown handler (Esc, Tab/Shift+Tab).              */
/*  - The hamburger button has an explicit aria-label.                       */
/*  - ListItemButton provides built‑in keyboard activation (Enter/Space).    */
/*  - All icons are decorative; they receive no extra label.                */
/* -------------------------------------------------------------------------- */
