  // 1. Click to open/close
  // -----------------------------------------------------------------
  it('opens and closes the drawer via hamburger click', async () => {
    renderWithRouter(<AppDrawer tabs={testTabs} />);

    const hamburger = screen.getByLabelText(/open app drawer/i);
    expect(hamburger).toBeInTheDocument();

    // Initially closed
    expect(screen.queryByRole('navigation', { hidden: false })).not.toBeInTheDocument();

    // Open
    await userEvent.click(hamburger);
    const drawer = screen.getByRole('navigation', { hidden: false });
    expect(drawer).toBeInTheDocument();

    // Close via hamburger again
    await userEvent.click(hamburger);
    expect(screen.queryByRole('navigation', { hidden: false })).not.toBeInTheDocument();
  });

  // -----------------------------------------------------------------
  // 2. Swipe to open (left‑to‑right) and close (right‑to‑left)
  // -----------------------------------------------------------------
  it('opens drawer on left‑to‑right swipe and closes on right‑to‑left swipe', async () => {
    renderWithRouter(<AppDrawer tabs={testTabs} />);

    const hamburger = screen.getByLabelText(/open app drawer/i);
    const drawer = screen.getByRole('navigation', { hidden: true }); // initially hidden via CSS transform

    // Simulate touch start at x=100, move to x=200 (> threshold)
    await userEvent.touchStart(hamburger, { touchStartX: 100 });
    await userEvent.touchMove(hamburger, { touchMoveX: 200 });
    await userEvent.touchEnd(hamburger);

    expect(localStorageMock.setItem).toHaveBeenCalledWith('appDrawerOpen', 'true');
    expect(drawer).toHaveClass('MuiDrawer-open'); // MUI adds this class when open

    // Now close via swipe right‑to‑left (starting inside drawer)
    const drawerPaper = within(drawer).getByRole('navigation');
    await userEvent.touchStart(drawerPaper, { touchStartX: 250 });
    await userEvent.touchMove(drawerPaper, { touchMoveX: 100 });
    await userEvent.touchEnd(drawerPaper);

    expect(localStorageMock.setItem).toHaveBeenCalledWith('appDrawerOpen', 'false');
    expect(drawer).not.toHaveClass('MuiDrawer-open');
  });

  // -----------------------------------------------------------------
  // 3. Active tab highlighting
  // -----------------------------------------------------------------
  it('highlights the tab that matches the current location', async () => {
    // Start on /orders
    renderWithRouter(<AppDrawer tabs={testTabs} />, { initialEntries: ['/orders'] });

    await userEvent.click(screen.getByLabelText(/open app drawer/i));

    const ordersItem = screen.getByRole('option', { name: /orders/i });
    expect(ordersItem).toHaveClass('Mui-selected'); // MUI ListItemButton selected state

    // Change location to /products
    // We need to re‑render with a new location; easiest is to unmount & render again.
    // However, to keep the test simple we simulate a push via history (MemoryRouter).
    // We'll wrap the component in a function that accepts location prop.
