  // -----------------------------------------------------------------
  it('persists open state in localStorage and restores on mount', async () => {
    // Simulate a previous session where drawer was left open
    (localStorageMock.getItem as jest.Mock).mockReturnValueOnce('true');

    renderWithRouter(<AppDrawer tabs={testTabs} />);
    // Drawer should be open immediately because we read from storage
    const drawer = screen.getByRole('navigation', { hidden: false });
    expect(drawer).toBeInTheDocument();

    // Close it via hamburger
    await userEvent.click(screen.getByLabelText(/open app drawer/i));
    expect(localStorageMock.setItem).toHaveBeenCalledWith('appDrawerOpen', 'false');

    // Now simulate a fresh page load with storage set to false
    (localStorageMock.getItem as jest.Mock).mockReturnValueOnce('false');
    renderWithRouter(<AppDrawer tabs={testTabs} />);
    expect(screen.queryByRole('navigation', { hidden: false })).not.toBeInTheDocument();
  });

  // -----------------------------------------------------------------
  // 5. Basic accessibility checks (role, aria-label, focusable)
  // -----------------------------------------------------------------
  it('has correct ARIA attributes and trap focus when open', async () => {
    renderWithRouter(<AppDrawer tabs={testTabs} />);
    await userEvent.click(screen.getByLabelText(/open app drawer/i));

    const drawer = screen.getByRole('navigation');
    expect(drawer).toHaveAttribute('role', 'navigation');
    expect(drawer).toHaveAttribute('aria-label', /app drawer/i);

