## 3. ROBUST IMPLEMENTATION LOGIC (ALGORITHMIC SPEC)

### 3.1 `usePersistedDrawerState` Hook (Replace `useRefObject` mess)
```typescript
function usePersistedDrawerState(): UseDrawerStateReturn {
  // 1. Initialize from localStorage (SSR safe)
  const [isOpen, setIsOpen] = useLocalStorage<boolean>('app-drawer-open', false);

  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const previousActiveElement = useRef<HTMLElement | null>(null);

  // 2. Focus Management on Open/Close
  const open = useCallback(() => {
    previousActiveElement.current = document.activeElement as HTMLElement;
    setIsOpen(true);
    // Focus trap setup handled in useEffect below
  }, [setIsOpen]);

  const close = useCallback(() => {
    setIsOpen(false);
    // Restore focus to trigger AFTER state update + paint
    requestAnimationFrame(() => {
      triggerRef.current?.focus({ preventScroll: true });
    });
  }, [setIsOpen]);

  const toggle = useCallback(() => (isOpen ? close() : open()), [isOpen, open, close]);

  // 3. Focus Trap & ARIA Management (Runs on isOpen change)
  useEffect(() => {
    const panel = panelRef.current;
    const trigger = triggerRef.current;
    if (!panel) return;

    if (isOpen) {
      // ARIA
      panel.setAttribute('aria-hidden', 'false');
      trigger?.setAttribute('aria-expanded', 'true');
      document.body.style.overflow = 'hidden'; // Scroll lock

      // Focus First Focusable Element
      const focusable = panel.querySelector<HTMLElement>('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
      focusable?.focus({ preventScroll: true });

      // Trap Logic
      const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key !== 'Tab') return;
        const focusables = Array.from(panel.querySelectorAll<HTMLElement>('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'));
        const first = focusables[0];
        const last = focusables[focusables.length - 1];

        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault(); last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault(); first.focus();
        }
      };
      panel.addEventListener('keydown', handleKeyDown);
      return () => {
        panel.removeEventListener('keydown', handleKeyDown);
        document.body.style.overflow = '';
        panel.setAttribute('aria-hidden', 'true');
        trigger?.setAttribute('aria-expanded', 'false');
      };
    } else {
      // Closed state cleanup handled in return above
    }
  }, [isOpen]);

  // 4. Escape Key Global Listener
  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) close();
    };
    document.addEventListener('keydown', handleEscape);
    return () => document.removeEventListener('keydown', handleEscape);
  }, [isOpen, close]);

  return { isOpen, open, close, toggle, triggerRef, panelRef };
}
```

### 3.2 `useSwipeGesture` Hook (Attach to Layout Wrapper)
```typescript
function useSwipeGesture(onOpen: () => void, onClose: () => void, isOpen: boolean): UseSwipeGestureReturn {
  const touchStartX = useRef(0);
  const touchStartY = useRef(0);
  const SWIPE_THRESHOLD = 80; // px
  const VERTICAL_THRESHOLD = 50; // px - ignore vertical scroll

  const onTouchStart = useCallback((e: React.TouchEvent<HTMLDivElement>) => {
    if (isOpen) return; // Only swipe to OPEN from closed state (standard UX)
    touchStartX.current = e.touches[0].clientX;
    touchStartY.current = e.touches[0].clientY;
  }, [isOpen]);

  const onTouchMove = useCallback((e: React.TouchEvent<HTMLDivElement>) => {
    // Optional: Visual drag feedback (transformX) - omitted for brevity, but recommended
  }, []);

  const onTouchEnd = useCallback((e: React.TouchEvent<HTMLDivElement>) => {
    if (isOpen) return;
    const dx = e.changedTouches[0].clientX - touchStartX.current;
    const dy = Math.abs(e.changedTouches[0].clientY - touchStartY.current);

    // Swipe Right (Open) from Left Edge
    if (dx > SWIPE_THRESHOLD && dy < VERTICAL_THRESHOLD && touchStartX.current < 50) {
      onOpen();
    }
  }, [isOpen, onOpen]);

  return { onTouchStart, onTouchMove, onTouchEnd };
}
```

### 3.3 `AppDrawer` Component Composition
```tsx
export const AppDrawer: React.FC<AppDrawerProps> = ({ 
  items, 
  activePath, 
  onNavigate, 
  zIndex = 1200 
}) => {
  const { 
    isOpen, 
    open, 
    close, 
    toggle, 
    triggerRef, 
    panelRef 
  } = usePersistedDrawerState();

  // Render Hamburger Button (Trigger)
  const HamburgerButton = () => (
    <button
      ref={triggerRef}
      type="button"
      className={styles.hamburger}
      onClick={toggle}
      aria-label={isOpen ? 'Close navigation menu' : 'Open navigation menu'}
      aria-expanded={isOpen}
      aria-controls="app-drawer-panel"
    >
      <span className={clsx(styles.hamburgerLine, isOpen && styles.hamburgerLine--open)} aria-hidden="true" />
      <span className={clsx(styles.hamburgerLine, isOpen && styles.hamburgerLine--open)} aria-hidden="true" />
      <span className={clsx(styles.hamburgerLine, isOpen && styles.hamburgerLine--open)} aria-hidden="true" />
    </button>
  );

  // Render Drawer Panel (Portal to body or fixed position in layout)
  const DrawerPanel = () => (
    <>
      <div
        className={clsx(styles.overlay, isOpen && styles.overlay--visible)}
        onClick={close}
        aria-hidden="true"
      />
      <aside
        ref={panelRef}
        id="app-drawer-panel"
        role="navigation"
        aria-label="Main navigation"
        className={clsx(styles.drawer, isOpen && styles.drawer--open)}
        style={{ zIndex, width: 'var(--drawer-width)' }}
        aria-hidden={!isOpen}
      >
        <nav className={styles.navList}>
          {items.map((item) => (
            <button
              key={item.id}
              type="button"
              className={clsx(styles.navItem, activePath === item.id && styles.navItem--active)}
              onClick={() => { onNavigate(item.id); close(); }}
              aria-current={activePath === item.id ? 'page' : undefined}
              aria-label={item.ariaLabel || item.label}
            >
              <span className={styles.navItemIcon} aria-hidden="true">{item.icon}</span>
              <span className={styles.navItemLabel}>{item.label}</span>
            </button>
          ))}
        </nav>
      </aside>
    </>
  );

  return (
    <>
      <HamburgerButton />
      <DrawerPanel />
    </>
  );
};
```

